import React, { useState, useEffect } from 'react';
import { API_BASE } from '../services/api';

const ConfiguracionSMTP = () => {
  const [configs, setConfigs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testEmail, setTestEmail] = useState('');
  const [message, setMessage] = useState({ type: '', text: '' });
  const [editingId, setEditingId] = useState(null);
  
  const [formData, setFormData] = useState({
    name: 'Configuración Principal',
    host: '',
    port: 587,
    username: '',
    password: '',
    from_email: '',
    from_name: 'Sistema de Correos',
    use_tls: true,
    use_ssl: false,
    timeout: 30,
    is_default: false
  });

  useEffect(() => {
    loadConfigs();
  }, []);

  const loadConfigs = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE}/smtp-config/`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (response.ok) {
        const data = await response.json();
        setConfigs(data.items || []);
        
        // Si hay una configuración, cargarla en el formulario
        if (data.items && data.items.length > 0) {
          const defaultConfig = data.items.find(c => c.is_default) || data.items[0];
          setFormData({
            name: defaultConfig.name,
            host: defaultConfig.host,
            port: defaultConfig.port,
            username: defaultConfig.username,
            password: '', // No mostrar contraseña por seguridad
            from_email: defaultConfig.from_email,
            from_name: defaultConfig.from_name,
            use_tls: defaultConfig.use_tls,
            use_ssl: defaultConfig.use_ssl,
            timeout: defaultConfig.timeout,
            is_default: defaultConfig.is_default
          });
          setEditingId(defaultConfig.id);
        }
      }
    } catch (error) {
      showMessage('error', 'Error al cargar configuraciones');
    } finally {
      setLoading(false);
    }
  };

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: '', text: '' }), 5000);
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : (type === 'number' ? parseInt(value) : value)
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    
    try {
      const token = localStorage.getItem('token');
      const url = editingId 
        ? `${API_BASE}/smtp-config/${editingId}`
        : `${API_BASE}/smtp-config/`;
      const method = editingId ? 'PUT' : 'POST';
      
      const submitData = { ...formData };
      // Si la contraseña está vacía y estamos editando, no enviarla
      if (!submitData.password && editingId) {
        delete submitData.password;
      }
      
      const response = await fetch(url, {
        method,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(submitData)
      });
      
      if (response.ok) {
        const savedConfig = await response.json();
        setEditingId(savedConfig.id);
        showMessage('success', 'Configuración guardada exitosamente');
        loadConfigs();
      } else {
        const error = await response.json();
        showMessage('error', error.detail || 'Error al guardar configuración');
      }
    } catch (error) {
      showMessage('error', 'Error de conexión');
    } finally {
      setSaving(false);
    }
  };

  const testConnection = async (useTestEmail = false) => {
    if (!formData.host || !formData.username || !formData.password) {
      showMessage('error', 'Complete host, usuario y contraseña para probar');
      return;
    }
    
    if (useTestEmail && !testEmail) {
      showMessage('error', 'Ingrese un correo de prueba');
      return;
    }
    
    setTesting(true);
    
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE}/smtp-config/test`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          host: formData.host,
          port: formData.port,
          username: formData.username,
          password: formData.password,
          use_tls: formData.use_tls,
          use_ssl: formData.use_ssl,
          test_email: useTestEmail ? testEmail : null
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        showMessage('success', `✅ ${result.message}`);
      } else {
        showMessage('error', `❌ ${result.message}: ${result.details || ''}`);
      }
    } catch (error) {
      showMessage('error', 'Error al probar conexión');
    } finally {
      setTesting(false);
    }
  };

  const setAsDefault = async (configId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE}/smtp-config/${configId}/set-default`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (response.ok) {
        showMessage('success', 'Configuración establecida como predeterminada');
        loadConfigs();
      }
    } catch (error) {
      showMessage('error', 'Error al establecer como predeterminada');
    }
  };

  const toggleActive = async (configId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE}/smtp-config/${configId}/toggle-active`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (response.ok) {
        showMessage('success', 'Estado actualizado');
        loadConfigs();
      }
    } catch (error) {
      showMessage('error', 'Error al cambiar estado');
    }
  };

  const deleteConfig = async (configId) => {
    if (!window.confirm('¿Está seguro de eliminar esta configuración?')) {
      return;
    }
    
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API_BASE}/smtp-config/${configId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (response.ok) {
        showMessage('success', 'Configuración eliminada');
        setEditingId(null);
        loadConfigs();
        // Reset form
        setFormData({
          name: 'Nueva Configuración',
          host: '',
          port: 587,
          username: '',
          password: '',
          from_email: '',
          from_name: 'Sistema de Correos',
          use_tls: true,
          use_ssl: false,
          timeout: 30,
          is_default: false
        });
      }
    } catch (error) {
      showMessage('error', 'Error al eliminar');
    }
  };

  const loadConfigToForm = (config) => {
    setFormData({
      name: config.name,
      host: config.host,
      port: config.port,
      username: config.username,
      password: '',
      from_email: config.from_email,
      from_name: config.from_name,
      use_tls: config.use_tls,
      use_ssl: config.use_ssl,
      timeout: config.timeout,
      is_default: config.is_default
    });
    setEditingId(config.id);
  };

  const newConfig = () => {
    setFormData({
      name: 'Nueva Configuración',
      host: '',
      port: 587,
      username: '',
      password: '',
      from_email: '',
      from_name: 'Sistema de Correos',
      use_tls: true,
      use_ssl: false,
      timeout: 30,
      is_default: false
    });
    setEditingId(null);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-gray-500">Cargando configuración...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">⚙️ Configuración SMTP</h2>
          <p className="text-gray-600 mt-1">Configure los parámetros del servidor de correo</p>
        </div>
        <button
          onClick={newConfig}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition flex items-center gap-2"
        >
          ➕ Nueva Configuración
        </button>
      </div>

      {/* Message */}
      {message.text && (
        <div className={`p-4 rounded-lg ${
          message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
        }`}>
          {message.text}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Form */}
        <div className="lg:col-span-2">
          <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow p-6 space-y-4">
            <h3 className="text-lg font-semibold text-gray-800 border-b pb-2">
              {editingId ? 'Editar Configuración' : 'Nueva Configuración'}
            </h3>

            {/* Basic Info */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Nombre de la Configuración
                </label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="Mi Configuración SMTP"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Timeout (segundos)
                </label>
                <input
                  type="number"
                  name="timeout"
                  value={formData.timeout}
                  onChange={handleChange}
                  min="5"
                  max="300"
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            </div>

            {/* Server Settings */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Servidor SMTP *
                </label>
                <input
                  type="text"
                  name="host"
                  value={formData.host}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="smtp.gmail.com"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Puerto *
                </label>
                <input
                  type="number"
                  name="port"
                  value={formData.port}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  min="1"
                  max="65535"
                  required
                />
              </div>
            </div>

            {/* Credentials */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Usuario / Email *
                </label>
                <input
                  type="text"
                  name="username"
                  value={formData.username}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="usuario@gmail.com"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Contraseña *
                </label>
                <input
                  type="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="••••••••"
                  required={!editingId}
                />
                {editingId && (
                  <p className="text-xs text-gray-500 mt-1">Dejar vacío para mantener contraseña actual</p>
                )}
              </div>
            </div>

            {/* From Settings */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Email Remitente *
                </label>
                <input
                  type="email"
                  name="from_email"
                  value={formData.from_email}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="noreply@empresa.com"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Nombre del Remitente
                </label>
                <input
                  type="text"
                  name="from_name"
                  value={formData.from_name}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="Sistema de Correos"
                />
              </div>
            </div>

            {/* Security Options */}
            <div className="bg-gray-50 rounded-lg p-4">
              <h4 className="text-sm font-medium text-gray-700 mb-3">Seguridad</h4>
              <div className="flex flex-wrap gap-6">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    name="use_tls"
                    checked={formData.use_tls}
                    onChange={handleChange}
                    className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700">Usar STARTTLS (Puerto 587)</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    name="use_ssl"
                    checked={formData.use_ssl}
                    onChange={handleChange}
                    className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700">Usar SSL (Puerto 465)</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    name="is_default"
                    checked={formData.is_default}
                    onChange={handleChange}
                    className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700">Configuración predeterminada</span>
                </label>
              </div>
            </div>

            {/* Actions */}
            <div className="flex flex-wrap gap-3 pt-4 border-t">
              <button
                type="submit"
                disabled={saving}
                className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 flex items-center gap-2"
              >
                {saving ? '⏳' : '💾'} {saving ? 'Guardando...' : 'Guardar Configuración'}
              </button>
              
              <button
                type="button"
                onClick={() => testConnection(false)}
                disabled={testing}
                className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition disabled:opacity-50 flex items-center gap-2"
              >
                {testing ? '⏳' : '🔍'} Probar Conexión
              </button>
              
              {editingId && (
                <button
                  type="button"
                  onClick={() => deleteConfig(editingId)}
                  className="bg-red-600 text-white px-6 py-2 rounded-lg hover:bg-red-700 transition flex items-center gap-2"
                >
                  🗑️ Eliminar
                </button>
              )}
            </div>
          </form>

          {/* Test Email Section */}
          <div className="bg-white rounded-lg shadow p-6 mt-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">📧 Enviar Correo de Prueba</h3>
            <div className="flex gap-3">
              <input
                type="email"
                value={testEmail}
                onChange={(e) => setTestEmail(e.target.value)}
                className="flex-1 border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="correo@ejemplo.com"
              />
              <button
                onClick={() => testConnection(true)}
                disabled={testing || !testEmail}
                className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 transition disabled:opacity-50 flex items-center gap-2"
              >
                📤 Enviar Prueba
              </button>
            </div>
            <p className="text-xs text-gray-500 mt-2">
              Se enviará un correo de prueba a la dirección especificada para verificar la configuración
            </p>
          </div>
        </div>

        {/* Configurations List */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">📋 Configuraciones Guardadas</h3>
            
            {configs.length === 0 ? (
              <p className="text-gray-500 text-center py-4">
                No hay configuraciones guardadas
              </p>
            ) : (
              <div className="space-y-3">
                {configs.map(config => (
                  <div
                    key={config.id}
                    className={`p-4 rounded-lg border-2 cursor-pointer transition ${
                      editingId === config.id
                        ? 'border-blue-500 bg-blue-50'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                    onClick={() => loadConfigToForm(config)}
                  >
                    <div className="flex items-start justify-between">
                      <div>
                        <h4 className="font-medium text-gray-800">{config.name}</h4>
                        <p className="text-sm text-gray-600">{config.host}:{config.port}</p>
                        <p className="text-xs text-gray-500">{config.username}</p>
                      </div>
                      <div className="flex flex-col gap-1">
                        {config.is_default && (
                          <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded">
                            ⭐ Predeterminada
                          </span>
                        )}
                        <span className={`text-xs px-2 py-1 rounded ${
                          config.is_active
                            ? 'bg-green-100 text-green-800'
                            : 'bg-red-100 text-red-800'
                        }`}>
                          {config.is_active ? '✅ Activa' : '❌ Inactiva'}
                        </span>
                      </div>
                    </div>
                    
                    <div className="flex gap-2 mt-3">
                      {!config.is_default && (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            setAsDefault(config.id);
                          }}
                          className="text-xs bg-yellow-500 text-white px-2 py-1 rounded hover:bg-yellow-600"
                        >
                          ⭐ Predeterminar
                        </button>
                      )}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleActive(config.id);
                        }}
                        className={`text-xs px-2 py-1 rounded ${
                          config.is_active
                            ? 'bg-red-500 text-white hover:bg-red-600'
                            : 'bg-green-500 text-white hover:bg-green-600'
                        }`}
                      >
                        {config.is_active ? ' Desactivar' : '▶ Activar'}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Help */}
          <div className="bg-blue-50 rounded-lg p-4 mt-4">
            <h4 className="font-medium text-blue-800 mb-2">💡 Ayuda</h4>
            <ul className="text-sm text-blue-700 space-y-1">
              <li>• <strong>Gmail:</strong> smtp.gmail.com:587 (STARTTLS)</li>
              <li>• <strong>Outlook:</strong> smtp.office365.com:587</li>
              <li>• <strong>Yahoo:</strong> smtp.mail.yahoo.com:465 (SSL)</li>
            </ul>
            <p className="text-xs text-blue-600 mt-2">
              Nota: Para Gmail, use una contraseña de aplicación, no su contraseña normal.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ConfiguracionSMTP;
